import { useState, useEffect, useCallback, useRef } from 'react';
import { RotateCcw, Trophy } from 'lucide-react';
import Board from './components/Board';
import { Grid, createEmptyGrid, addRandomTile, move, hasWon, canMove, Direction } from './utils/game';

export default function App() {
  const [grid, setGrid] = useState<Grid>(() => addRandomTile(addRandomTile(createEmptyGrid())));
  const [score, setScore] = useState(0);
  const [best, setBest] = useState(() => Number(localStorage.getItem('best2048') || 0));
  const [won, setWon] = useState(false);
  const [over, setOver] = useState(false);
  const [keepGoing, setKeepGoing] = useState(false);

  const reset = useCallback(() => {
    setGrid(addRandomTile(addRandomTile(createEmptyGrid())));
    setScore(0);
    setWon(false);
    setOver(false);
    setKeepGoing(false);
  }, []);

  const handleMove = useCallback((dir: Direction) => {
    if (over) return;
    if (won && !keepGoing) return;
    setGrid(prev => {
      const { grid: moved, gained, changed } = move(prev, dir);
      if (!changed) return prev;
      const next = addRandomTile(moved);
      setScore(s => {
        const ns = s + gained;
        setBest(b => {
          const nb = Math.max(b, ns);
          localStorage.setItem('best2048', String(nb));
          return nb;
        });
        return ns;
      });
      if (!won && hasWon(next)) setWon(true);
      if (!canMove(next)) setOver(true);
      return next;
    });
  }, [over, won, keepGoing]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const map: Record<string, Direction> = {
        ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right',
        w: 'up', s: 'down', a: 'left', d: 'right',
      };
      const dir = map[e.key];
      if (dir) {
        e.preventDefault();
        handleMove(dir);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [handleMove]);

  const touchStart = useRef<{ x: number; y: number } | null>(null);
  const onTouchStart = (e: React.TouchEvent) => {
    const t = e.touches[0];
    touchStart.current = { x: t.clientX, y: t.clientY };
  };
  const onTouchEnd = (e: React.TouchEvent) => {
    if (!touchStart.current) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - touchStart.current.x;
    const dy = t.clientY - touchStart.current.y;
    const ax = Math.abs(dx), ay = Math.abs(dy);
    if (Math.max(ax, ay) < 24) return;
    if (ax > ay) handleMove(dx > 0 ? 'right' : 'left');
    else handleMove(dy > 0 ? 'down' : 'up');
    touchStart.current = null;
  };

  return (
    <div className="min-h-screen bg-[#faf8ef] flex items-center justify-center p-6">
      <div className="w-full max-w-md">
        <div className="flex items-end justify-between mb-6">
          <div>
            <h1 className="text-5xl font-extrabold text-[#776e65] leading-none">2048</h1>
            <p className="text-[#776e65] text-sm mt-2">타일을 합쳐 2048을 만드세요</p>
          </div>
          <div className="flex gap-2">
            <div className="bg-[#bbada0] rounded-lg px-4 py-2 text-center min-w-[72px]">
              <div className="text-[#eee4da] text-xs font-bold uppercase">점수</div>
              <div className="text-white text-xl font-bold">{score}</div>
            </div>
            <div className="bg-[#bbada0] rounded-lg px-4 py-2 text-center min-w-[72px]">
              <div className="text-[#eee4da] text-xs font-bold uppercase flex items-center justify-center gap-1"><Trophy size={12} />최고</div>
              <div className="text-white text-xl font-bold">{best}</div>
            </div>
          </div>
        </div>

        <div className="flex justify-between items-center mb-4">
          <p className="text-sm text-[#776e65]">방향키 또는 스와이프로 이동</p>
          <button
            onClick={reset}
            className="flex items-center gap-2 bg-[#8f7a66] hover:bg-[#7d6a58] text-white font-bold px-4 py-2 rounded-lg transition-colors"
          >
            <RotateCcw size={16} /> 새 게임
          </button>
        </div>

        <div className="relative" onTouchStart={onTouchStart} onTouchEnd={onTouchEnd}>
          <Board grid={grid} />
          {(over || (won && !keepGoing)) && (
            <div className="absolute inset-0 bg-white/70 rounded-xl flex flex-col items-center justify-center gap-4">
              <p className="text-3xl font-extrabold text-[#776e65]">
                {over ? '게임 오버!' : '승리!'}
              </p>
              <div className="flex gap-3">
                {won && !over && (
                  <button
                    onClick={() => setKeepGoing(true)}
                    className="bg-[#edc22e] hover:bg-[#e0b71f] text-white font-bold px-5 py-2.5 rounded-lg transition-colors"
                  >
                    계속하기
                  </button>
                )}
                <button
                  onClick={reset}
                  className="bg-[#8f7a66] hover:bg-[#7d6a58] text-white font-bold px-5 py-2.5 rounded-lg transition-colors"
                >
                  다시 시작
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

