export type Grid = number[][];
export type Direction = 'up' | 'down' | 'left' | 'right';

export function createEmptyGrid(): Grid {
  return Array.from({ length: 4 }, () => Array(4).fill(0));
}

export function addRandomTile(grid: Grid): Grid {
  const empty: [number, number][] = [];
  for (let r = 0; r < 4; r++)
    for (let c = 0; c < 4; c++)
      if (grid[r][c] === 0) empty.push([r, c]);
  if (empty.length === 0) return grid;
  const next = grid.map(row => [...row]);
  const [r, c] = empty[Math.floor(Math.random() * empty.length)];
  next[r][c] = Math.random() < 0.9 ? 2 : 4;
  return next;
}

function slideRow(row: number[]): { row: number[]; gained: number } {
  const filtered = row.filter(v => v !== 0);
  const result: number[] = [];
  let gained = 0;
  for (let i = 0; i < filtered.length; i++) {
    if (i + 1 < filtered.length && filtered[i] === filtered[i + 1]) {
      const merged = filtered[i] * 2;
      result.push(merged);
      gained += merged;
      i++;
    } else {
      result.push(filtered[i]);
    }
  }
  while (result.length < 4) result.push(0);
  return { row: result, gained };
}

function transpose(grid: Grid): Grid {
  return grid[0].map((_, c) => grid.map(row => row[c]));
}

export function move(grid: Grid, dir: Direction): { grid: Grid; gained: number; changed: boolean } {
  let working = grid.map(row => [...row]);
  const reverse = dir === 'right' || dir === 'down';
  const vertical = dir === 'up' || dir === 'down';

  if (vertical) working = transpose(working);
  let gained = 0;
  working = working.map(row => {
    const input = reverse ? [...row].reverse() : row;
    const { row: slid, gained: g } = slideRow(input);
    gained += g;
    return reverse ? slid.reverse() : slid;
  });
  if (vertical) working = transpose(working);

  const changed = JSON.stringify(working) !== JSON.stringify(grid);
  return { grid: working, gained, changed };
}

export function hasWon(grid: Grid): boolean {
  return grid.some(row => row.some(v => v >= 2048));
}

export function canMove(grid: Grid): boolean {
  for (let r = 0; r < 4; r++)
    for (let c = 0; c < 4; c++) {
      if (grid[r][c] === 0) return true;
      if (c + 1 < 4 && grid[r][c] === grid[r][c + 1]) return true;
      if (r + 1 < 4 && grid[r][c] === grid[r + 1][c]) return true;
    }
  return false;
}
